generateQR.handler:
function generateQR(args, ctx) {
  try {
    if (typeof window === "undefined" || !window.QREngine || typeof window.QREngine.create !== "function") {
      ctx.triggerActionEvent("error", { error: "QR engine not loaded yet." })
      return
    }
    var qr = window.QREngine.create(args.config || {})
    window.__lastQR = qr

    // Resolve qr.svg which may be: an SVG string, a renderer function (opts) => svg,
    // or a function that returns yet another function. Keep unwrapping (bounded) until
    // we get a real string. Never inject a stringified function into the DOM.
    var svg = qr && qr.svg
    var guard = 0
    while (typeof svg === "function" && guard < 5) {
      svg = svg({ pxSize: 512 })
      guard++
    }

    var isMarkup = (typeof svg === "string") && /<svg[\s>]/i.test(svg)

    if (isMarkup && args.targetId) {
      var el = document.getElementById(args.targetId)
      if (el) {
        el.innerHTML = svg
        var svgEl = el.querySelector("svg")
        if (svgEl) {
          // Preserve intrinsic ratio via viewBox, then let CSS size it responsively.
          if (!svgEl.getAttribute("viewBox")) {
            var w = parseFloat(svgEl.getAttribute("width")) || 512
            var h = parseFloat(svgEl.getAttribute("height")) || 512
            svgEl.setAttribute("viewBox", "0 0 " + w + " " + h)
          }
          svgEl.removeAttribute("width")
          svgEl.removeAttribute("height")
          svgEl.style.width = "100%"
          svgEl.style.height = "100%"
          svgEl.style.maxWidth = "100%"
          svgEl.style.maxHeight = "100%"
          svgEl.style.display = "block"
        }
      }
    }

    if (!isMarkup) {
      ctx.triggerActionEvent("error", { error: "QR engine did not return valid SVG markup." })
      return
    }

    ctx.triggerActionEvent("result", {
      svg: svg,
      info: qr && qr.info,
      analysis: qr && qr.analysis,
      error: qr && qr.error
    })
  } catch (e) {
    ctx.triggerActionEvent("error", { error: (e && e.message) ? e.message : String(e) })
  }
}

downloadQR.handler:
function downloadQR(args, ctx) {
  try {
    var qr = (typeof window !== "undefined") ? window.__lastQR : null
    if (!qr) {
      ctx.triggerActionEvent("error", { error: "No QR code has been generated yet." })
      return
    }
    if (args.format === "svg") {
      if (typeof qr.downloadSVG === "function") { qr.downloadSVG() }
    } else {
      if (typeof qr.downloadPNG === "function") { qr.downloadPNG(args.px || 1024) }
    }
  } catch (e) {
    ctx.triggerActionEvent("error", { error: (e && e.message) ? e.message : String(e) })
  }
}

uploadLogo.handler:
function uploadLogo(args, ctx) {
  try {
    var file = args.file
    if (!file || typeof FileReader === "undefined") {
      ctx.triggerActionEvent("error", { error: "No file selected." })
      return
    }
    if (file.type && file.type.indexOf("image/") !== 0) {
      ctx.triggerActionEvent("error", { error: "Please choose an image file." })
      return
    }
    var reader = new FileReader()
    reader.onload = function () {
      ctx.triggerActionEvent("result", { dataUrl: reader.result })
    }
    reader.onerror = function () {
      ctx.triggerActionEvent("error", { error: "Could not read the file." })
    }
    reader.readAsDataURL(file)
  } catch (e) {
    ctx.triggerActionEvent("error", { error: (e && e.message) ? e.message : String(e) })
  }
}

