    if (res.status === 409) ({ res, id } = await tryInsert());

    if (res.status === 403 || res.status === 401) throw new Error('PAYWALL');
    if (!res.ok) throw new Error('CREATE_FAILED_' + res.status + ': ' + await res.text());

    ctx.triggerActionEvent("result", { url: 'https://qr.engineer/' + id, id: id });
