qrSvg.handler:
function qrSvg(args, ctx) {
  var text = (args.text == null || String(args.text).length === 0) ? "https://nordcraft.com" : String(args.text);
  var fg = args.fg || "#0b0f0c";
  var bg = args.bg || "#f5f7f5";
  var shape = args.shape || "square";
  var pxSize = Number(args.size) || 320;
  var quiet = (args.margin == null) ? 4 : Number(args.margin);

  var EXP = new Array(512);
  var LOG = new Array(256);
  var x0 = 1;
  for (var e = 0; e < 255; e++) {
    EXP[e] = x0;
    LOG[x0] = e;
    x0 = x0 << 1;
    if (x0 & 0x100) x0 = x0 ^ 0x11d;
  }
  for (var e2 = 255; e2 < 512; e2++) EXP[e2] = EXP[e2 - 255];
  function gfMul(a, b) { return (a === 0 || b === 0) ? 0 : EXP[LOG[a] + LOG[b]]; }

  function rsGenPoly(n) {
    var poly = [1];
    for (var i = 0; i < n; i++) {
      var next = new Array(poly.length + 1).fill(0);
      for (var j = 0; j < poly.length; j++) {
        next[j] = next[j] ^ poly[j];
        next[j + 1] = next[j + 1] ^ gfMul(poly[j], EXP[i]);
      }
      poly = next;
    }
    return poly;
  }
  function rsEncode(data, ecLen) {
    var gen = rsGenPoly(ecLen);
    var res = data.slice().concat(new Array(ecLen).fill(0));
    for (var i = 0; i < data.length; i++) {
      var coef = res[i];
      if (coef !== 0) {
        for (var j = 0; j < gen.length; j++) res[i + j] = res[i + j] ^ gfMul(gen[j], coef);
      }
    }
    return res.slice(data.length);
  }

  var VER = {};
  VER[1] = { ec: 10, g1: 1, d1: 16, g2: 0, d2: 0 };
  VER[2] = { ec: 16, g1: 1, d1: 28, g2: 0, d2: 0 };
  VER[3] = { ec: 26, g1: 1, d1: 44, g2: 0, d2: 0 };
  VER[4] = { ec: 18, g1: 2, d1: 32, g2: 0, d2: 0 };
  VER[5] = { ec: 24, g1: 2, d1: 43, g2: 0, d2: 0 };
  VER[6] = { ec: 16, g1: 4, d1: 27, g2: 0, d2: 0 };
  VER[7] = { ec: 18, g1: 4, d1: 31, g2: 0, d2: 0 };
  VER[8] = { ec: 22, g1: 2, d1: 38, g2: 2, d2: 39 };
  VER[9] = { ec: 22, g1: 3, d1: 36, g2: 2, d2: 37 };
  VER[10] = { ec: 26, g1: 4, d1: 43, g2: 1, d2: 44 };

  var bytes = [];
  for (var ci = 0; ci < text.length; ci++) {
    var c = text.charCodeAt(ci);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) { bytes.push(0xc0 | (c >> 6)); bytes.push(0x80 | (c & 0x3f)); }
    else { bytes.push(0xe0 | (c >> 12)); bytes.push(0x80 | ((c >> 6) & 0x3f)); bytes.push(0x80 | (c & 0x3f)); }
  }

  var version = 0, cfg = null;
  for (var v = 1; v <= 10; v++) {
    var c2 = VER[v];
    var dataCw2 = c2.g1 * c2.d1 + c2.g2 * c2.d2;
    var lb = (v <= 9) ? 8 : 16;
    if (4 + lb + bytes.length * 8 <= dataCw2 * 8) { version = v; cfg = c2; break; }
  }
  if (!version) { return "<svg xmlns='http://www.w3.org/2000/svg'></svg>"; }

  var totalDataCw = cfg.g1 * cfg.d1 + cfg.g2 * cfg.d2;
  var lenBits = (version <= 9) ? 8 : 16;

  var bits = [];
  function pushBits(val, len) { for (var b = len - 1; b >= 0; b--) bits.push((val >> b) & 1); }
  pushBits(0x4, 4);
  pushBits(bytes.length, lenBits);
  for (var bi = 0; bi < bytes.length; bi++) pushBits(bytes[bi], 8);
  var cap = totalDataCw * 8;
  var term = Math.min(4, cap - bits.length);
  for (var t = 0; t < term; t++) bits.push(0);
  while (bits.length % 8 !== 0) bits.push(0);
  var padBytes = [0xec, 0x11], pi = 0;
  while (bits.length < cap) { pushBits(padBytes[pi % 2], 8); pi++; }

  var dataCodewords = [];
  for (var dii = 0; dii < bits.length; dii += 8) {
    var byteVal = 0;
    for (var b2 = 0; b2 < 8; b2++) byteVal = (byteVal << 1) | bits[dii + b2];
    dataCodewords.push(byteVal);
  }

  var blocks = [];
  var idx = 0;
  for (var g = 0; g < cfg.g1; g++) { blocks.push(dataCodewords.slice(idx, idx + cfg.d1)); idx += cfg.d1; }
  for (var gg = 0; gg < cfg.g2; gg++) { blocks.push(dataCodewords.slice(idx, idx + cfg.d2)); idx += cfg.d2; }
  var ecBlocks = blocks.map(function (blk) { return rsEncode(blk, cfg.ec); });

  var finalCw = [];
  var maxData = 0;
  for (var mb = 0; mb < blocks.length; mb++) if (blocks[mb].length > maxData) maxData = blocks[mb].length;
  for (var cc0 = 0; cc0 < maxData; cc0++) {
    for (var bIdx = 0; bIdx < blocks.length; bIdx++) {
      if (cc0 < blocks[bIdx].length) finalCw.push(blocks[bIdx][cc0]);
    }
  }
  for (var c3 = 0; c3 < cfg.ec; c3++) {
    for (var bIdx2 = 0; bIdx2 < ecBlocks.length; bIdx2++) finalCw.push(ecBlocks[bIdx2][c3]);
  }

  var N = version * 4 + 17;
  var mat = [];
  var reserved = [];
  for (var r0 = 0; r0 < N; r0++) { mat.push(new Array(N).fill(0)); reserved.push(new Array(N).fill(false)); }

  function setModule(r, c, val) { mat[r][c] = val ? 1 : 0; reserved[r][c] = true; }
  function placeFinder(r, c) {
    for (var dr = -1; dr <= 7; dr++) {
      for (var dc = -1; dc <= 7; dc++) {
        var rr = r + dr, ccc = c + dc;
        if (rr < 0 || rr >= N || ccc < 0 || ccc >= N) continue;
        var on = (dr >= 0 && dr <= 6 && (dc === 0 || dc === 6)) ||
                 (dc >= 0 && dc <= 6 && (dr === 0 || dr === 6)) ||
                 (dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4);
        setModule(rr, ccc, on ? 1 : 0);
      }
    }
  }
  placeFinder(0, 0);
  placeFinder(0, N - 7);
  placeFinder(N - 7, 0);

  for (var ti = 8; ti < N - 8; ti++) {
    setModule(6, ti, (ti % 2 === 0) ? 1 : 0);
    setModule(ti, 6, (ti % 2 === 0) ? 1 : 0);
  }
  setModule(N - 8, 8, 1);

  var ALIGN = {};
  ALIGN[1] = []; ALIGN[2] = [6, 18]; ALIGN[3] = [6, 22]; ALIGN[4] = [6, 26]; ALIGN[5] = [6, 30];
  ALIGN[6] = [6, 34]; ALIGN[7] = [6, 22, 38]; ALIGN[8] = [6, 24, 42]; ALIGN[9] = [6, 26, 46]; ALIGN[10] = [6, 28, 50];
  var aps = ALIGN[version];
  for (var a1 = 0; a1 < aps.length; a1++) {
    for (var a2 = 0; a2 < aps.length; a2++) {
      var ar = aps[a1], ac = aps[a2];
      if (reserved[ar][ac]) continue;
      for (var dr2 = -2; dr2 <= 2; dr2++) {
        for (var dc2 = -2; dc2 <= 2; dc2++) {
          var on2 = (Math.abs(dr2) === 2 || Math.abs(dc2) === 2 || (dr2 === 0 && dc2 === 0));
          setModule(ar + dr2, ac + dc2, on2 ? 1 : 0);
        }
      }
    }
  }

  for (var fi = 0; fi <= 8; fi++) {
    reserved[8][fi] = true;
    reserved[fi][8] = true;
  }
  for (var fj = 0; fj < 8; fj++) {
    reserved[8][N - 1 - fj] = true;
    reserved[N - 1 - fj][8] = true;
  }

  var dataBits = [];
  for (var fw = 0; fw < finalCw.length; fw++) for (var b3 = 7; b3 >= 0; b3--) dataBits.push((finalCw[fw] >> b3) & 1);
  var bitPtr = 0;
  var upward = true;
  for (var col = N - 1; col > 0; col -= 2) {
    if (col === 6) col = 5;
    for (var rowStep = 0; rowStep < N; rowStep++) {
      var row = upward ? (N - 1 - rowStep) : rowStep;
      for (var cOff = 0; cOff < 2; cOff++) {
        var cc = col - cOff;
        if (reserved[row][cc]) continue;
        var bit = (bitPtr < dataBits.length) ? dataBits[bitPtr] : 0;
        bitPtr++;
        mat[row][cc] = bit;
      }
    }
    upward = !upward;
  }

  function maskFn(m, r, c) {
    if (m === 0) return (r + c) % 2 === 0;
    if (m === 1) return r % 2 === 0;
    if (m === 2) return c % 3 === 0;
    if (m === 3) return (r + c) % 3 === 0;
    if (m === 4) return (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0;
    if (m === 5) return ((r * c) % 2) + ((r * c) % 3) === 0;
    if (m === 6) return (((r * c) % 2) + ((r * c) % 3)) % 2 === 0;
    return (((r + c) % 2) + ((r * c) % 3)) % 2 === 0;
  }

  function formatBits(mask) {
    var ecBits = 0;
    var data = (ecBits << 3) | mask;
    var gpoly = 0x537;
    var bch = data << 10;
    for (var i = 14; i >= 10; i--) { if ((bch >> i) & 1) bch = bch ^ (gpoly << (i - 10)); }
    var full = ((data << 10) | (bch & 0x3ff)) ^ 0x5412;
    var arr = [];
    for (var k = 14; k >= 0; k--) arr.push((full >> k) & 1);
    return arr;
  }
  function placeFormat(mask) {
    var f = formatBits(mask);
    var idxs = [[8,0],[8,1],[8,2],[8,3],[8,4],[8,5],[8,7],[8,8],[7,8],[5,8],[4,8],[3,8],[2,8],[1,8],[0,8]];
    for (var i = 0; i < 15; i++) { var p = idxs[i]; mat[p[0]][p[1]] = f[i]; }
    for (var q = 0; q < 8; q++) mat[8][N - 1 - q] = f[q];
    for (var w = 0; w < 7; w++) mat[N - 7 + w][8] = f[8 + w];
    mat[N - 8][8] = 1;
  }

  function penalty(g) {
    var score = 0;
    for (var r = 0; r < N; r++) {
      var run = 1;
      for (var c = 1; c < N; c++) {
        if (g[r][c] === g[r][c - 1]) { run++; } else { if (run >= 5) score += run - 2; run = 1; }
      }
      if (run >= 5) score += run - 2;
    }
    for (var cx2 = 0; cx2 < N; cx2++) {
      var run2 = 1;
      for (var r2 = 1; r2 < N; r2++) {
        if (g[r2][cx2] === g[r2 - 1][cx2]) { run2++; } else { if (run2 >= 5) score += run2 - 2; run2 = 1; }
      }
      if (run2 >= 5) score += run2 - 2;
    }
    for (var r3 = 0; r3 < N - 1; r3++) {
      for (var c4 = 0; c4 < N - 1; c4++) {
        var val = g[r3][c4];
        if (val === g[r3][c4 + 1] && val === g[r3 + 1][c4] && val === g[r3 + 1][c4 + 1]) score += 3;
      }
    }
    var dark = 0;
    for (var r4 = 0; r4 < N; r4++) for (var c5 = 0; c5 < N; c5++) dark += g[r4][c5];
    var pct = (dark * 100) / (N * N);
    var five = Math.floor(Math.abs(pct - 50) / 5);
    score += five * 10;
    return score;
  }

  var bestMask = 0, bestScore = Infinity, bestGrid = null;
  for (var m = 0; m < 8; m++) {
    var g = [];
    for (var r = 0; r < N; r++) {
      g.push(mat[r].slice());
      for (var c = 0; c < N; c++) {
        if (!reserved[r][c]) { if (maskFn(m, r, c)) g[r][c] = g[r][c] ^ 1; }
      }
    }
    var pen = penalty(g);
    if (pen < bestScore) { bestScore = pen; bestMask = m; bestGrid = g; }
  }
  mat = bestGrid;
  placeFormat(bestMask);

  var scale = pxSize / (N + quiet * 2);
  var svgW = pxSize;
  function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
  var parts = [];
  parts.push("<svg xmlns='http://www.w3.org/2000/svg' width='" + svgW + "' height='" + svgW + "' viewBox='0 0 " + svgW + " " + svgW + "' shape-rendering='crispEdges'>");
  parts.push("<rect width='" + svgW + "' height='" + svgW + "' fill='" + esc(bg) + "'/>");

  var s = scale;
  var off = quiet * scale;
  for (var rr2 = 0; rr2 < N; rr2++) {
    for (var cc2 = 0; cc2 < N; cc2++) {
      if (mat[rr2][cc2] !== 1) continue;
      var xx = off + cc2 * s;
      var yy = off + rr2 * s;
      if (shape === "dots") {
        var cxp = xx + s / 2, cyp = yy + s / 2, rad = s * 0.45;
        parts.push("<circle cx='" + cxp.toFixed(2) + "' cy='" + cyp.toFixed(2) + "' r='" + rad.toFixed(2) + "' fill='" + esc(fg) + "'/>");
      } else if (shape === "rounded") {
        var rr3 = s * 0.28;
        parts.push("<rect x='" + xx.toFixed(2) + "' y='" + yy.toFixed(2) + "' width='" + s.toFixed(2) + "' height='" + s.toFixed(2) + "' rx='" + rr3.toFixed(2) + "' ry='" + rr3.toFixed(2) + "' fill='" + esc(fg) + "'/>");
      } else {
        parts.push("<rect x='" + xx.toFixed(2) + "' y='" + yy.toFixed(2) + "' width='" + (s + 0.5).toFixed(2) + "' height='" + (s + 0.5).toFixed(2) + "' fill='" + esc(fg) + "'/>");
      }
    }
  }
  parts.push("</svg>");
  return parts.join("");
}
